Ваш код содержит несколько проблем, которые необходимо исправить для того, чтобы подменю открывалось и закрывалось корректно при каждом клике на ссылку. Основные проблемы:

1. Вы проверяете наличие `.menu .menu_sub`, что может быть некорректно, если у вас несколько уровней подменю.
2. Вы добавляете элемент в массив `arr`, но забываете проверить наличие открытого подменю перед его открытием.

Исправленный код будет выглядеть следующим образом:

```javascript
let arr = [];

function toggleSubMenu(event) {
    event.preventDefault(); // Предотвращаем стандартное действие ссылки

    const thisClosest = this.closest('.menu__item');
    if (!thisClosest) return;

    const subMenu = thisClosest.querySelector('.menu_sub'); // Получаем подменю

    // Если подменю уже открыто, закрываем его
    if (subMenu.classList.contains('menu_active')) {
        subMenu.classList.remove('menu_active');
        arr = arr.filter(item => item !== subMenu); // Удаляем из массива
    } else {
        // Если подменю не открыто, открываем его
        arr.forEach(item => item.classList.remove('menu_active')); // Закрываем все открытые подменю
        subMenu.classList.add('menu_active');
        arr.push(subMenu); // Добавляем текущее подменю в массив
    }
}

let menuLinks = document.querySelectorAll('.menu__link');
menuLinks.forEach(link => link.addEventListener('click', toggleSubMenu));
```

