#include <iostream>
using namespace std;

void printY(int n) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            // Conditions for printing '*'
            if ((i == j) || (j == n - i - 1)) {
                cout << "* ";
            } else {
                cout << "  ";
            }
        }
        cout << endl;
    }
}

void printH(int n) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            // Conditions for printing '*'
            if (j == n / 2 || i == n / 2) {
                cout << "* ";
            } else {
                cout << "  ";
            }
        }
        cout << endl;
    }
}

int main() {
    int n;
    cout << "Enter the number of lines: ";
    cin >> n;

    // Ensure n is odd for symmetry
    if (n % 2 == 0) {
        n++;
    }

    cout << "Y: ";
    printY(n);
    cout << "H: ";
    printH(n);

    return 0;
}
```

