    public static void main (String [] args)
    {
        // Loading the original image
        SimpleIO.showMessage("Ready for original image?");
        MyroColorImage picture = new MyroColorImage();
        picture.resize(400, 400);
        picture.show();

        // Create a new image with the same dimensions as the original
        MyroColorImage pic2 = new MyroColorImage(picture.getWidth(), picture.getHeight());

        // Show message for orientation change
        SimpleIO.showMessage("Ready for orientation change?");

        // Looping through each pixel in the original image
        for (MyroPixel pixel : picture)
        {
            // Calculate the corresponding y coordinate for the flipped image
            int y2 = picture.getHeight() - pixel.getY() - 1;

            // Set the new pixel value in the flipped image
            MyroPixel other = pic2.getPixel(pixel.getX(), y2);
