### Пример реализации

```cpp
#include <iostream>
#include <vector>
#include <Eigen/Dense>

// Виртуальный класс procedure_iface
template <class T>
class procedure_iface {
public:
    using trace = Eigen::Matrix<T, Eigen::Dynamic, 1>;
    using block = Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic, Eigen::RowMajor>;
    using value_type = T;

    procedure_iface() = default;
    procedure_iface(const procedure_iface<T>&) = default;
    procedure_iface(procedure_iface<T>&&) noexcept = default;

    procedure_iface<T>& operator=(const procedure_iface<T>&) = default;
    procedure_iface<T>& operator=(procedure_iface<T>&&) noexcept = default;

    virtual ~procedure_iface() = default;

    // Will throw exception if procedure doesn't support trace based processing
    virtual void run(const Eigen::Ref<const trace>& in, Eigen::Ref<trace> out) = 0;

    // Will throw exception if procedure doesn't support block based processing
    virtual void run(const Eigen::Ref<const block>& in, Eigen::Ref<block> out) = 0;

    virtual parallel_type type_parallel() = 0;
};

// Конкретный подкласс для обработки трейсов
template <class T>
class TraceProcessor : public procedure_iface<T> {
public:
    using base_type = procedure_iface<T>;
    using trace = typename base_type::trace;
    using block = typename base_type::block;
    using value_type = typename base_type::value_type;

    TraceProcessor() {}

    void run(const Eigen::Ref<const trace>& in, Eigen::Ref<trace> out) override {
        for (int i = 0; i < in.size(); ++i) {
            out(i) = in(i) * 2;  // Простой пример умножения на 2
        }
    }

    void run(const Eigen::Ref<const block>&, Eigen::Ref<block>) override {
        throw std::runtime_error("TraceProcessor does not support block-based processing");
    }

    parallel_type type_parallel() override {
        return parallel_type::sequential;
    }
};

