```cpp
#include <iostream>
using namespace std;

void printLetterY(int n) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            // Condition for printing '*' in letter Y
            if (j == 0 || i == j || i + j == n - 1)
                cout << "*";
            else
                cout << " ";
        }
        cout << "  ";  // Add space between letters
    }
}

void printLetterH(int n) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            // Condition for printing '*' in letter H
            if (j == n / 2 || i == n / 2)
                cout << "*";
            else
                cout << " ";
        }
        cout << "  ";  // Add space between letters
    }
}

int main() {
    int n;
    cout << "Enter the number of lines: ";
    cin >> n;

    cout << "\nPrinting Y and H:\n";

    printLetterY(n);
    printLetterH(n);

    return 0;
}
```

