```python
import time
from functools import wraps

def retry_decorator(max_retries):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            max_retries_count = max_retries
            current_retry = 0

            while current_retry < max_retries_count:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    print(f"Попытка {current_retry + 1}/{max_retries_count} завершилась ошибкой: {e}")
                    time.sleep(2)  # Подождать перед следующей попыткой
                    current_retry += 1

            raise Exception(f"Не удалось выполнить функцию после {max_retries_count} попыток.")
        return wrapper
    return decorator
```

