    for (int i = 0; i < numLines; ++i) {
        // Inner loop for printing stars for Y
        for (int j = 0; j < numLines; ++j) {
            if ((i == j || j == numLines - 1 - i) && i <= numLines / 2) {
                std::cout << "*";
            } else {
