def retry(func, *args, **kwargs):
    def wrapper(*args, **kwargs):
        retries = 0
        while retries < kwargs['max_retries']:
            try:
                result = func(*args, **kwargs)
                return result
            except Exception as e:
                print(f"Connection failed with error: {e}, retrying in {kwargs['delay']} seconds...")
                time.sleep(kwargs['delay'])
                retries += 1
                kwargs['delay'] *= kwargs['backoff']
                if retries >= kwargs['max_retries']:
                    raise e
    return wrapper

