```python
from PIL import Image
import numpy as np

def text_to_binary(text):
    return ''.join(format(ord(char), '08b') for char in text)

def binary_to_text(binary):
    text = ''
    for i in range(0, len(binary), 8):
        byte = binary[i:i+8]
        if byte:
            text += chr(int(byte, 2))
    return text

def embed_text_in_image(image_path, text, output_path):
    # Load the image
    img = Image.open(image_path)
    binary_text = text_to_binary(text + '\x00')  # Null character to mark end of text

    # Convert image to numpy array
    pixels = np.array(img)

    # Check if the image has enough bits to hide the text
    if len(binary_text) > pixels.size * 3:  # Each pixel has 3 colors (RGB)
        raise ValueError("The image is too small to hide the given text.")

    # Embed the text
    index = 0
    for row in range(pixels.shape[0]):
        for col in range(pixels.shape[1]):
            for color in range(pixels.shape[2]):
                if index < len(binary_text):
                    pixels[row, col, color] = pixels[row, col, color] & ~1 | int(binary_text[index])
                    index += 1

    # Save the modified image
    new_img = Image.fromarray(pixels)
    new_img.save(output_path)

def extract_text_from_image(image_path):
    img = Image.open(image_path)
    pixels = np.array(img)

    binary_text = ''
    for row in range(pixels.shape[0]):
        for col in range(pixels.shape[1]):
            for color in range(pixels.shape[2]):
                binary_text += str(pixels[row, col, color] & 1)

