    public static void main (String [] args)
    {
        // Loading the original image
        SimpleIO.showMessage("Ready for original image?");
        MyroColorImage picture = new MyroColorImage();
        picture.resize(400,400);
        picture.show();

        // Create a new image with the same dimensions as the original
        MyroColorImage flippedPicture = new MyroColorImage(picture.getWidth(), picture.getHeight());

        SimpleIO.showMessage("Ready for orientation change?");

        // Loop through each pixel in the original image
        for (MyroPixel pixel : picture) 
        {
            int x = pixel.getX();
            int y = pixel.getY();

            // Calculate the flipped coordinates
            int flippedX = x;
            int flippedY = picture.getHeight() - y - 1;

            // Get the pixel at the flipped coordinates and set its color
            MyroPixel flippedPixel = flippedPicture.getPixel(flippedX, flippedY);
            flippedPixel.setColor(pixel.getColor());
        }

        // Show the flipped image
        flippedPicture.show();

        SimpleIO.showMessage("Flipped image shown.");
    }
}
```

